"""Build the reviewable SDD document set from four retained source files.

This script creates documentation, source transcriptions and illustrative contracts.
It does not implement or execute a crawler.
"""
from pathlib import Path
from hashlib import sha256
from datetime import datetime
import json
import re
from docx import Document
from docx.oxml.ns import qn

ROOT = Path(__file__).resolve().parents[1]
SOURCE_DIR = ROOT / "docs"
OUT = ROOT / "specs/001-public-knowledge-collection"
DATE = "2026-09-11"
META = "版本：0.1.0｜日期：2026-09-11｜状态：评审草案，尚未批准为实施基线\n\n"

def write(path, text):
    p = ROOT / path
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text.rstrip() + "\n", encoding="utf-8")

def doc(name, title, text):
    write(OUT.relative_to(ROOT) / name, "# " + title + "\n\n" + META + text)

def dump(name, value):
    write(OUT.relative_to(ROOT) / name, json.dumps(value, ensure_ascii=False, indent=2))

SOURCES = [
    ("S1", "一般爬虫采集与标准化数据交付需求规范_V1.1_仅采集整理.docx"),
    ("S2", "七类知识库知识来源与采集方案_V1.3_宽泛检索关键词版.docx"),
    ("S3", "需求审查_共同要求.md"),
    ("S4", "需求审查_差异与单方要求.md"),
]

def source_transcripts():
    entries = []
    register = OUT / "sources/source-register.json"
    previous = {e["id"]: e for e in json.loads(register.read_text(encoding="utf-8"))} if register.exists() else {}
    for sid, name in SOURCES:
        p = SOURCE_DIR / name
        entry = dict(id=sid, filename=name, path=f"docs/{name}", bytes=p.stat().st_size,
                     sha256=sha256(p.read_bytes()).hexdigest())
        if "relocation_history" in previous.get(sid, {}):
            entry["relocation_history"] = previous[sid]["relocation_history"]
        entries.append(entry)
        if p.suffix != ".docx":
            continue
        d = Document(p)
        text = [f"# {sid} 原文结构转录\n\n", f"原件：[ {name} ](../../../docs/{name})\n\n",
                "此文件按 Word 主文档 XML 顺序转录段落和表格，供定位原文使用；不代替原件的排版、图像或批注。"
                "B 编号表示主文档直接子元素的序号，空段落计入编号但不显示。表格中的换行以 HTML 换行标记表示。\n\n"]
        for i, e in enumerate(d.element.body, 1):
            if e.tag == qn("w:tbl"):
                rows = []
                for row in e.findall(qn("w:tr")):
                    cells = []
                    for cell in row.findall(qn("w:tc")):
                        paras = ["".join(t.text or "" for t in par.iter(qn("w:t"))) for par in cell.findall(qn("w:p"))]
                        cells.append("<br>".join(paras).replace("|", "\\|"))
                    rows.append(cells)
                if rows:
                    width = max(map(len, rows))
                    rows = [r + [""] * (width - len(r)) for r in rows]
                    text += [f"## B{i:03d}\n\n", "| " + " | ".join(rows[0]) + " |\n",
                             "| " + " | ".join(["---"] * width) + " |\n"]
                    text += ["| " + " | ".join(r) + " |\n" for r in rows[1:]]
                    text.append("\n")
            else:
                s = "".join(t.text or "" for t in e.iter(qn("w:t")))
                if s.strip():
                    text += [f"## B{i:03d}\n\n", s + "\n\n"]
        write(OUT.relative_to(ROOT) / f"sources/{sid}-transcript.md", "".join(text))
    dump("sources/source-register.json", entries)
    return entries

# Requirements are the single authoring source for the specification,
# acceptance scenarios, traceability matrix and implementation task mapping.
# Fields: ID, title, scope, force, evidence, story, module, task, open decisions,
#         required behavior, test fixture and action, expected observation.
R = []
def req(*fields):
    keys = "id title scope force source story module task issues behavior action expected".split()
    assert len(keys) == len(fields)
    R.append(dict(zip(keys, fields)))

