def build_contracts():
    def s(desc="", minimum=0):
        return {"type":"string", **({"minLength":minimum} if minimum else {}), "description":desc}
    def arr(desc=""):
        return {"type":"array", "items":{"type":"string"}, "description":desc}
    def date(nullable=False):
        return {"type":["string","null"] if nullable else "string", "format":"date"}
    timestamp = {"type":"string", "format":"date-time"}
